import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Send, Upload, Settings, Play, Square, BarChart3, FileText, AlertCircle } from 'lucide-react';
import './App.css';

const API_URL = 'http://localhost:8000/api';

function App() {
  const [status, setStatus] = useState('idle');
  const [config, setConfig] = useState(null);
  const [logs, setLogs] = useState([]);
  const [statistics, setStatistics] = useState(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [uploadedFile, setUploadedFile] = useState(null);

  useEffect(() => {
    fetchStatus();
    fetchConfig();
    const interval = setInterval(fetchStatus, 2000);
    return () => clearInterval(interval);
  }, []);

  const fetchStatus = async () => {
    try {
      const response = await axios.get(`${API_URL}/status`);
      setStatus(response.data.status);
      setLogs(response.data.logs || []);
    } catch (error) {
      console.error('Erro ao buscar status:', error);
    }
  };

  const fetchConfig = async () => {
    try {
      const response = await axios.get(`${API_URL}/config`);
      setConfig(response.data);
    } catch (error) {
      console.error('Erro ao buscar config:', error);
    }
  };

  const fetchStatistics = async () => {
    try {
      const response = await axios.get(`${API_URL}/statistics`);
      setStatistics(response.data);
    } catch (error) {
      console.error('Erro ao buscar estatísticas:', error);
    }
  };

  const startCampaign = async () => {
    try {
      await axios.post(`${API_URL}/start-campaign`, config);
      fetchStatus();
    } catch (error) {
      console.error('Erro ao iniciar campanha:', error);
    }
  };

  const stopCampaign = async () => {
    try {
      await axios.post(`${API_URL}/stop-campaign`);
      fetchStatus();
    } catch (error) {
      console.error('Erro ao parar campanha:', error);
    }
  };

  const handleFileUpload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const formData = new FormData();
    formData.append('file', file);

    try {
      const response = await axios.post(`${API_URL}/upload-csv`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });

      setUploadedFile(response.data);

      // Atualiza config com novo arquivo
      const newConfig = { ...config, arquivo_leads: response.data.filepath };
      await axios.post(`${API_URL}/config`, newConfig);
      setConfig(newConfig);

    } catch (error) {
      console.error('Erro ao fazer upload:', error);
    }
  };

  const updateConfig = async (key, value) => {
    const newConfig = { ...config, [key]: value };
    setConfig(newConfig);
    await axios.post(`${API_URL}/config`, newConfig);
  };

  const getStatusColor = () => {
    switch (status) {
      case 'running': return 'text-green-500';
      case 'completed': return 'text-blue-500';
      case 'error': return 'text-red-500';
      default: return 'text-gray-500';
    }
  };

  const getStatusText = () => {
    switch (status) {
      case 'running': return 'Em Execução';
      case 'completed': return 'Concluído';
      case 'error': return 'Erro';
      case 'stopped': return 'Parado';
      default: return 'Aguardando';
    }
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white">
      <div className="container mx-auto px-4 py-8">
        <header className="mb-8">
          <h1 className="text-3xl font-bold flex items-center gap-3">
            <Send className="text-green-500" />
            WhatsApp Automation
          </h1>
          <p className="text-gray-400 mt-2">Sistema de automação de envio de mensagens</p>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <div className="bg-gray-800 rounded-lg p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-400 text-sm">Status</p>
                <p className={`text-2xl font-bold ${getStatusColor()}`}>{getStatusText()}</p>
              </div>
              <div className={`w-3 h-3 rounded-full ${status === 'running' ? 'bg-green-500 animate-pulse' : 'bg-gray-500'}`} />
            </div>
          </div>

          <div className="bg-gray-800 rounded-lg p-6">
            <div>
              <p className="text-gray-400 text-sm">Enviados</p>
              <p className="text-2xl font-bold text-green-500">{statistics?.campaign_state?.sent || 0}</p>
            </div>
          </div>

          <div className="bg-gray-800 rounded-lg p-6">
            <div>
              <p className="text-gray-400 text-sm">Falhas</p>
              <p className="text-2xl font-bold text-red-500">{statistics?.campaign_state?.failed || 0}</p>
            </div>
          </div>

          <div className="bg-gray-800 rounded-lg p-6">
            <div>
              <p className="text-gray-400 text-sm">Progresso</p>
              <p className="text-2xl font-bold text-blue-500">{statistics?.campaign_state?.progress || 0}%</p>
            </div>
          </div>
        </div>

        <div className="flex gap-4 mb-8">
          <button
            onClick={() => setActiveTab('dashboard')}
            className={`px-4 py-2 rounded-lg ${activeTab === 'dashboard' ? 'bg-green-600' : 'bg-gray-700'}`}
          >
            <BarChart3 className="inline mr-2" size={18} />
            Dashboard
          </button>
          <button
            onClick={() => setActiveTab('upload')}
            className={`px-4 py-2 rounded-lg ${activeTab === 'upload' ? 'bg-green-600' : 'bg-gray-700'}`}
          >
            <Upload className="inline mr-2" size={18} />
            Upload CSV
          </button>
          <button
            onClick={() => setActiveTab('config')}
            className={`px-4 py-2 rounded-lg ${activeTab === 'config' ? 'bg-green-600' : 'bg-gray-700'}`}
          >
            <Settings className="inline mr-2" size={18} />
            Configurações
          </button>
          <button
            onClick={() => setActiveTab('logs')}
            className={`px-4 py-2 rounded-lg ${activeTab === 'logs' ? 'bg-green-600' : 'bg-gray-700'}`}
          >
            <FileText className="inline mr-2" size={18} />
            Logs
          </button>
        </div>

        <div className="flex gap-4 mb-8">
          {status !== 'running' ? (
            <button
              onClick={startCampaign}
              className="bg-green-600 hover:bg-green-700 px-6 py-3 rounded-lg font-semibold flex items-center gap-2"
            >
              <Play size={20} />
              Iniciar Campanha
            </button>
          ) : (
            <button
              onClick={stopCampaign}
              className="bg-red-600 hover:bg-red-700 px-6 py-3 rounded-lg font-semibold flex items-center gap-2"
            >
              <Square size={20} />
              Parar Campanha
            </button>
          )}
        </div>

        {activeTab === 'dashboard' && (
          <div className="bg-gray-800 rounded-lg p-6">
            <h2 className="text-xl font-bold mb-4">Dashboard</h2>
            {uploadedFile ? (
              <div className="space-y-4">
                <div className="bg-gray-700 rounded p-4">
                  <h3 className="font-semibold mb-2">Arquivo Carregado</h3>
                  <p><strong>Nome:</strong> {uploadedFile.filename}</p>
                  <p><strong>Total de Leads:</strong> {uploadedFile.total_rows}</p>
                  <p><strong>Colunas:</strong> {uploadedFile.columns.join(', ')}</p>
                </div>

                <div className="bg-gray-700 rounded p-4">
                  <h3 className="font-semibold mb-2">Prévia dos Dados</h3>
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="border-b border-gray-600">
                          {uploadedFile.columns.map(col => (
                            <th key={col} className="text-left p-2">{col}</th>
                          ))}
                        </tr>
                      </thead>
                      <tbody>
                        {uploadedFile.preview.map((row, idx) => (
                          <tr key={idx} className="border-b border-gray-700">
                            {uploadedFile.columns.map(col => (
                              <td key={col} className="p-2">{String(row[col]).substring(0, 50)}</td>
                            ))}
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            ) : (
              <p className="text-gray-400">Nenhum arquivo carregado. Vá para a aba "Upload CSV".</p>
            )}
          </div>
        )}

        {activeTab === 'upload' && (
          <div className="bg-gray-800 rounded-lg p-6">
            <h2 className="text-xl font-bold mb-4">Upload CSV</h2>
            <div className="border-2 border-dashed border-gray-600 rounded-lg p-8 text-center">
              <Upload className="mx-auto mb-4 text-gray-400" size={48} />
              <p className="text-gray-400 mb-4">Arraste seu arquivo CSV aqui ou clique para selecionar</p>
              <input
                type="file"
                accept=".csv"
                onChange={handleFileUpload}
                className="hidden"
                id="file-upload"
              />
              <label
                htmlFor="file-upload"
                className="bg-green-600 hover:bg-green-700 px-6 py-3 rounded-lg cursor-pointer"
              >
                Selecionar Arquivo
              </label>
            </div>
          </div>
        )}

        {activeTab === 'config' && config && (
          <div className="bg-gray-800 rounded-lg p-6">
            <h2 className="text-xl font-bold mb-4">Configurações</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-gray-400 mb-2">Tamanho do Lote</label>
                <input
                  type="number"
                  value={config.lote_tamanho}
                  onChange={(e) => updateConfig('lote_tamanho', parseInt(e.target.value))}
                  className="w-full bg-gray-700 rounded p-3"
                />
              </div>
              <div>
                <label className="block text-gray-400 mb-2">Tempo Mínimo (s)</label>
                <input
                  type="number"
                  value={config.tempo_entre_msg_min}
                  onChange={(e) => updateConfig('tempo_entre_msg_min', parseInt(e.target.value))}
                  className="w-full bg-gray-700 rounded p-3"
                />
              </div>
              <div>
                <label className="block text-gray-400 mb-2">Tempo Máximo (s)</label>
                <input
                  type="number"
                  value={config.tempo_entre_msg_max}
                  onChange={(e) => updateConfig('tempo_entre_msg_max', parseInt(e.target.value))}
                  className="w-full bg-gray-700 rounded p-3"
                />
              </div>
              <div>
                <label className="block text-gray-400 mb-2">DDI Padrão</label>
                <input
                  type="text"
                  value={config.ddi_padrao}
                  onChange={(e) => updateConfig('ddi_padrao', e.target.value)}
                  className="w-full bg-gray-700 rounded p-3"
                />
              </div>
              <div className="md:col-span-2">
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={config.modo_teste}
                    onChange={(e) => updateConfig('modo_teste', e.target.checked)}
                    className="w-5 h-5"
                  />
                  <span>Modo Teste (não envia mensagens reais)</span>
                </label>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'logs' && (
          <div className="bg-gray-800 rounded-lg p-6">
            <h2 className="text-xl font-bold mb-4">Logs da Campanha</h2>
            <div className="bg-gray-900 rounded p-4 h-96 overflow-y-auto font-mono text-sm">
              {logs.length === 0 ? (
                <p className="text-gray-400">Nenhum log disponível</p>
              ) : (
                logs.map((log, idx) => (
                  <div key={idx} className="mb-2">
                    <span className="text-gray-500">{log.timestamp}</span>
                    <span className="ml-2">{log.message}</span>
                  </div>
                ))
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
